import{a as e,i as t,n,o as r,s as i}from"./Layout-TG6FpyL3.js";var a=e(),o=i(r(),1),s=t(),c=()=>(0,s.jsx)(`svg`,{viewBox:`0 0 24 24`,children:(0,s.jsx)(`path`,{d:`M7 17L17 7M17 7H8M17 7v9`})});function l(){return(0,s.jsxs)(n,{active:`about`,title:`About me — Kaung Myat Thu`,description:`My background in my own words — the shop floor, the warehouse, the writing, and what each one taught me.`,children:[(0,s.jsxs)(`article`,{className:`blog-post`,children:[(0,s.jsxs)(`header`,{className:`blog-hero`,children:[(0,s.jsx)(`span`,{className:`blog-hero-eyebrow`,children:`✦ Personal blog`}),(0,s.jsxs)(`h1`,{children:[`About `,(0,s.jsx)(`span`,{className:`grad`,children:`me.`})]}),(0,s.jsx)(`p`,{className:`blog-hero-sub`,children:`My own story — operations, content and systems, from a third-year civil failure to the AI book.`}),(0,s.jsxs)(`div`,{className:`blog-hero-meta`,children:[(0,s.jsx)(`span`,{children:`North Okkalapa`}),(0,s.jsx)(`span`,{className:`dot`}),(0,s.jsx)(`span`,{children:`Operations · Content · Systems`}),(0,s.jsx)(`span`,{className:`dot`}),(0,s.jsx)(`span`,{children:`+959955400017`})]})]}),(0,s.jsxs)(`div`,{className:`blog-stat-strip`,children:[(0,s.jsxs)(`div`,{className:`blog-stat`,children:[(0,s.jsxs)(`div`,{className:`blog-stat-num`,children:[`157K → `,(0,s.jsx)(`span`,{className:`accent`,children:`298K`})]}),(0,s.jsx)(`p`,{className:`blog-stat-label`,children:`Followers, 321 Ecolife (+90%)`})]}),(0,s.jsxs)(`div`,{className:`blog-stat`,children:[(0,s.jsxs)(`div`,{className:`blog-stat-num`,children:[`4 `,(0,s.jsx)(`span`,{className:`accent`,children:`months`})]}),(0,s.jsx)(`p`,{className:`blog-stat-label`,children:`CSM car-parts POS build`})]}),(0,s.jsxs)(`div`,{className:`blog-stat`,children:[(0,s.jsxs)(`div`,{className:`blog-stat-num`,children:[`3 `,(0,s.jsx)(`span`,{className:`accent`,children:`careers`})]}),(0,s.jsx)(`p`,{className:`blog-stat-label`,children:`NGO · 321 Ecolife · NPT Group`})]}),(0,s.jsxs)(`div`,{className:`blog-stat`,children:[(0,s.jsxs)(`div`,{className:`blog-stat-num`,children:[`Live `,(0,s.jsx)(`span`,{className:`accent`,children:`project`})]}),(0,s.jsx)(`p`,{className:`blog-stat-label`,children:`Myangustis — Burmese text engine`})]})]}),(0,s.jsxs)(`div`,{className:`blog-body`,children:[(0,s.jsx)(`p`,{children:`2012 was the start. My score was high enough to apply to any university. Back then engineering university was below MU and MMU, the medical universities. I had been disqualified at MU, and at that time I did not care much about the college. So I applied to random universities by writing top down to bottom, and got civil engineering — the highest major back then (today architecture is the highest).`}),(0,s.jsxs)(`p`,{children:[`At Hmaw Bi Technology University, civil engineering. I failed in the `,(0,s.jsx)(`b`,{children:`third year`}),` — as it became harder, and I played `,(0,s.jsx)(`b`,{children:`Dota 2`}),`. I regret it — not because I was stupid, but because I was not interested in that college. If I had gone to a computer college — which was below engineering university — I would not have failed. But I wrote the college form top down to bottom, so I did not get the computer college.`]}),(0,s.jsx)(`p`,{children:`Failing that third year gave me an AGTI certificate. That system changed during my second year — even though I passed, it became a full 6-year program, not a batch like the first two years AGTI and then two years BTech. Engineering, medical college, and Marine university students who failed can continue from the failed year if they move to distance education — as an example, if I moved to distance education and took physics or chemistry, my education would start from the third year and I would only have the third and fourth years left — graduated. If I take math, I can also continue from the failed year like that. Yangon University and YUFL are language colleges, not like the science-branch colleges, and YUFL English is a higher-level English college — so they don't roll to the first year. Engineering and medical colleges don't have English as a major subject, so they roll to the first year unless they take math, physics, chemistry and IC.`}),(0,s.jsx)(`p`,{children:`At first my aunt did not know. Instead of joining as a repeater in the third year, I went to KMD. Later she found out, and broke the support, so I worked some random jobs — a sales promoter, mobile sim-card selling, a move elsewhere. Then I re-rolled into the first year again. That had nothing to do with the support — I was already good in English, so I did not need to study much. Thanks to Dota 2, which is part of the reason I failed in civil.`}),(0,s.jsxs)(`p`,{children:[`In 2015 I was at KMD Institute for Practical A+ and Basic Network Engineering. The real English never came from any certificate. It came from `,(0,s.jsx)(`span`,{className:`hl`,children:`Dota 2`}),`, SEA-server IT, playing against international players.`]}),(0,s.jsx)(`p`,{children:`In 2020, final year before COVID, I worked at BAR, writing articles and posts for lifestyle and marketing, and collaborating with the marketing team to keep brand consistency.`}),(0,s.jsx)(`p`,{children:`In 2021–2022 I was Senior Logistic Officer at the NGO, C.D.A. My aunt backed me into the job. Many people had wanted it. I stayed home for one project and went to the field with the other two, one week or two between cities.`}),(0,s.jsxs)(`p`,{children:[`Then the rotation came. A rural state, too far, too poor, undeveloped. I quit. Not fired. I quit directly. It was not a bad job. The pay was fair and the work was real, but the role they wanted me to take was not the role I was willing to take, and no pay could bridge that.`,(0,s.jsx)(`br`,{}),(0,s.jsx)(`br`,{}),`I came back home, bought a `,(0,s.jsx)(`b`,{children:`Persian cat`}),` and decided to spend my life on the things I want to do. The relation with my aunt turned bad after that, and home turned into the opposite of what I imagined.`]}),(0,s.jsx)(`p`,{children:`The same time, I was a part-time Script Writer at Program.base, writing Burmese scripts for travel, infotainment and educational content.`}),(0,s.jsx)(`p`,{children:`For eight months in 2022 I had no job. Nobody did. It was the coup.`}),(0,s.jsx)(`p`,{children:`In 2022 I also started freelance translation work, literary and digital content.`}),(0,s.jsxs)(`p`,{children:[`My first project was media translation on Canal+ Myanmar's `,(0,s.jsx)(`i`,{children:`Alice Adventure`}),` programme. It paid little. The second came in 2023. The third project never came back. The friend who shared it died. He joined some organization for revolution.`]}),(0,s.jsx)(`p`,{children:`I met a girl. She was from a different city, and I fell in love. I did not want to stay home, so I left the cat with my aunt, who takes care of him, and I moved to Mawlamyine — her city.`}),(0,s.jsxs)(`p`,{children:[`Even though I had quit for the things I want to do, I needed a safety net again, and `,(0,s.jsx)(`a`,{href:`warehouse.html`,children:`NPT`}),` was the place — the job I took once I reached her city. Warehouse Supervisor, 6 January to 1 November 2024. Family-shared distributor, electronics and tools plus raw material. No software, no shelf maps, and nobody owned the stock. I registered every item every day.`]}),(0,s.jsx)(`p`,{children:`She cheated. I went back home.`}),(0,s.jsxs)(`p`,{children:[`I had the 321 interview lined up before I left Mawlamyine. Two days after I got back to Yangon I sat it, and two days after that I had the job. In November 2024 I started at `,(0,s.jsx)(`a`,{href:`work-record.html`,children:`321 Ecolife`}),` as Operation Assistant Supervisor, running the shop with no manager above me. Shop-floor operations, staff and TikTok. Followers went from 157,000 to 187,375 to `,(0,s.jsx)(`span`,{className:`hl`,children:`298,104`}),`, a `,(0,s.jsx)(`span`,{className:`hl`,children:`90% jump`}),` from October to December. 321 liked my stock management. I kept the floor running, then I quit. Not for any grudge. I wanted out of the operations loop and expand into `,(0,s.jsx)(`span`,{className:`hl`,children:`coding and digital marketing`}),`.`]}),(0,s.jsxs)(`p`,{children:[`In that era I wrote the `,(0,s.jsx)(`a`,{href:`ai.html`,children:`AI prompt book`}),`, a self-authored manuscript on how prompts shape LLM responses and how to read AI as a layered system. In 2025 I got a Conversion Optimization Certification from Skillshop, issued 30 Nov 2025 and expiring 30 Nov 2026.`]}),(0,s.jsxs)(`p`,{children:[`Everything after 321 was freelance, for survival and to help my finances. `,(0,s.jsx)(`b`,{children:`Yumeyuki`}),`, a Myanmar legal overseas employment agency, still alive. `,(0,s.jsx)(`b`,{children:`TTS-AE`}),`, built for his company. The friend works as an Airbnb co-host, and his boss gave him the portfolio-site task: a site and business mail for a bank, per their regulations. I followed his explanation as best I could. The mail is alive, and they keep using it.`]}),(0,s.jsxs)(`p`,{children:[(0,s.jsx)(`b`,{children:`Writermorphosis`}),`, a blog and book app, is deliberately down on the site. A friend is helping me hire for it; he does not need it. It is for me — I am drowning in Myangustis without income, and I am taking the risk.`]}),(0,s.jsxs)(`p`,{children:[(0,s.jsx)(`a`,{href:`warehouse.html`,children:`CSM`}),` — ချစ်စုမ, the car-parts shop — was project-based, not full-time. Four months, freelance. I go when I wake up and go home whenever I want. The one rule is that they don't like extra food, so no lunch at the shop. Shelf mapping, stock lists and POS in Excel. That Excel part is the `,(0,s.jsx)(`span`,{className:`hl`,children:`best part of my life`}),`.`]}),(0,s.jsxs)(`p`,{children:[`Right now I am on `,(0,s.jsx)(`a`,{href:`myangustis.html`,children:`Myangustis`}),`, my own Burmese toolkit, built from scratch: a segmenter and part-of-speech tagger with no regex in the tokenising, a grammar pass with no model and no language model, and around it a PDF parser, a scraper and a proofreading workflow. It is what my spare time goes to, outside freelance.`]}),(0,s.jsx)(`p`,{children:`In November 2026 I took a short-term role, a full-time content writer for one short-term contract. I quit after four days. It was not a good fit.`}),(0,s.jsx)(`p`,{children:`That is the story. Everything after 321 has been freelance, CSM included — some of it for money, all of it mine — and whatever spare time is left goes to Myangustis.`})]})]}),(0,s.jsxs)(`div`,{className:`blog-related`,children:[(0,s.jsx)(`span`,{className:`b-rel-title`,children:`Keep reading`}),(0,s.jsxs)(`div`,{className:`b-rel-links`,children:[(0,s.jsxs)(`a`,{href:`index.html`,children:[`Resume `,(0,s.jsx)(c,{})]}),(0,s.jsxs)(`a`,{href:`portfolio.html`,children:[`Portfolio `,(0,s.jsx)(c,{})]})]})]})]})}(0,a.createRoot)(document.getElementById(`root`)).render((0,s.jsx)(o.StrictMode,{children:(0,s.jsx)(l,{})}));